CREATE OR REPLACE FUNCTION public.consume_purchase_and_create_job(p_report_type text, p_job_payload jsonb, p_staged_files jsonb)
 RETURNS TABLE(job_id uuid, purchase_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'storage', 'auth', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_session_identifier text := coalesce(
    nullif(auth.jwt()->>'session_id', ''),
    nullif(auth.jwt()->>'jti', '')
  );
  v_job_id uuid;
  v_purchase_id uuid;
  v_product_identity text;
  v_report_family text;
  v_manifest jsonb;
  v_receipt_id uuid;
  v_file_count integer;
  v_object_count integer;
begin
  if v_uid is null then
    raise exception 'ADMISSION_UNAUTHENTICATED';
  end if;
  if p_report_type not in ('screening', 'underwriting') then
    raise exception 'ADMISSION_UNSUPPORTED_PRODUCT';
  end if;
  if v_session_identifier is null then
    raise exception 'ADMISSION_DISCLOSURE_SESSION_IDENTIFIER_MISSING';
  end if;

  if not exists (
    select 1
    from public.disclosure_session_ack_events d
    where d.user_id = v_uid
      and d.disclosure_key = 'analysis_disclosures'
      and d.disclosure_version = 'v2026-08-02'
      and d.disclosure_text_hash = '7387d8b79ba2ee22147bcc22ce01c50bbc8fee1856a25c0c04baf4dc8f028340'
      and d.session_identifier = v_session_identifier
  ) then
    raise exception 'ADMISSION_CURRENT_DISCLOSURE_SESSION_REQUIRED';
  end if;

  select x.job_id, x.purchase_id
    into v_job_id, v_purchase_id
  from public.consume_purchase_and_create_job_untrusted_legacy(
    p_report_type,
    p_job_payload,
    p_staged_files
  ) x
  limit 1;

  if v_job_id is null or v_purchase_id is null then
    raise exception 'ADMISSION_LEGACY_TRANSACTION_DID_NOT_RETURN_LINEAGE';
  end if;

  if not exists (
    select 1 from public.analysis_jobs j
    where j.id = v_job_id
      and j.user_id = v_uid
      and j.purchase_id = v_purchase_id
      and j.status = 'queued'
      and j.report_type = p_report_type
  ) then
    raise exception 'ADMISSION_JOB_LINEAGE_INVALID';
  end if;

  if not exists (
    select 1 from public.report_purchases p
    where p.id = v_purchase_id
      and p.user_id = v_uid
      and p.job_id = v_job_id
      and p.consumed_at is not null
      and p.product_type = p_report_type
  ) then
    raise exception 'ADMISSION_PURCHASE_LINEAGE_INVALID';
  end if;

  select count(*) into v_file_count
  from public.analysis_job_files f
  where f.job_id = v_job_id and f.user_id = v_uid;

  select count(*) into v_object_count
  from public.analysis_job_files f
  join storage.objects o
    on o.bucket_id = 'staged_uploads'
   and o.name = f.object_path
  where f.job_id = v_job_id
    and f.user_id = v_uid
    and f.bucket = 'staged_uploads'
    and o.name like ('staged/' || v_uid::text || '/%')
    and nullif(o.metadata->>'size', '') is not null
    and (o.metadata->>'size') ~ '^[0-9]+$'
    and (o.metadata->>'size')::bigint = f.bytes;

  if v_file_count < 2 or v_object_count <> v_file_count then
    raise exception 'ADMISSION_STAGED_OBJECT_METADATA_MISMATCH';
  end if;

  select jsonb_agg(
    jsonb_build_object(
      'job_file_id', f.id,
      'bucket', f.bucket,
      'object_path', f.object_path,
      'doc_type', f.doc_type,
      'bytes', f.bytes,
      'mime_type', f.mime_type,
      'storage_size', (o.metadata->>'size')::bigint,
      'storage_mimetype', o.metadata->>'mimetype',
      'storage_created_at', o.created_at,
      'storage_updated_at', o.updated_at
    ) order by f.created_at, f.id
  )
  into v_manifest
  from public.analysis_job_files f
  join storage.objects o
    on o.bucket_id = 'staged_uploads'
   and o.name = f.object_path
  where f.job_id = v_job_id and f.user_id = v_uid;

  v_product_identity := case when p_report_type = 'underwriting' then 'full_underwriting' else 'screening' end;
  v_report_family := v_product_identity;

  insert into public.analysis_job_admission_receipts (
    job_id, purchase_id, user_id, report_type, product_identity, report_family,
    disclosure_key, disclosure_version, disclosure_text_hash,
    disclosure_session_identifier, staged_source_manifest
  ) values (
    v_job_id, v_purchase_id, v_uid, p_report_type, v_product_identity, v_report_family,
    'analysis_disclosures', 'v2026-08-02',
    '7387d8b79ba2ee22147bcc22ce01c50bbc8fee1856a25c0c04baf4dc8f028340',
    v_session_identifier, coalesce(v_manifest, '[]'::jsonb)
  )
  returning id into v_receipt_id;

  update public.analysis_jobs
     set product_identity = v_product_identity,
         report_family = v_report_family,
         admission_receipt_id = v_receipt_id,
         terminal_domain = null,
         last_checkpoint = 'admitted',
         last_checkpoint_at = now()
   where id = v_job_id and user_id = v_uid;

  insert into public.analysis_job_events(job_id, actor, event_type, from_status, to_status, meta)
  values (
    v_job_id,
    'admission_authority',
    'job_admitted',
    null,
    'queued',
    jsonb_build_object(
      'admission_receipt_id', v_receipt_id,
      'purchase_id', v_purchase_id,
      'product_identity', v_product_identity,
      'report_family', v_report_family,
      'disclosure_version', 'v2026-08-02'
    )
  );

  job_id := v_job_id;
  purchase_id := v_purchase_id;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.consume_purchase_and_create_job_untrusted_legacy(p_report_type text, p_job_payload jsonb, p_staged_files jsonb)
 RETURNS TABLE(job_id uuid, purchase_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'storage', 'auth', 'pg_temp'
AS $function$
declare
  v_purchase_id uuid;
  v_product_type text;
  v_job_id uuid;
  v_file jsonb;
  v_storage_path text;
  v_path_prefix text;
  v_path_suffix text;
  v_path_segment text;
  v_original_name text;
  v_content_type text;
  v_size bigint;
  v_doc_type text;
  v_payload_doc_type text;
  v_has_t12 boolean := false;
  v_has_rent_roll boolean := false;
  v_has_supporting_docs boolean := false;
  v_seen_storage_paths text[] := array[]::text[];
  v_normalized_files jsonb := '[]'::jsonb;
  v_storage_object_row storage.objects%rowtype;
  v_object_size_text text;
begin
  if auth.uid() is null then
    raise exception 'UNAUTHORIZED';
  end if;

  if p_report_type is null or p_report_type not in ('screening','underwriting') then
    raise exception 'INVALID_REPORT_TYPE';
  end if;

  if p_staged_files is null or jsonb_typeof(p_staged_files) <> 'array' or jsonb_array_length(p_staged_files) = 0 then
    raise exception 'INVALID_STAGED_FILES';
  end if;

  for v_file in select * from jsonb_array_elements(p_staged_files) loop
    if v_file is null or jsonb_typeof(v_file) <> 'object' then
      raise exception 'INVALID_STAGED_FILES';
    end if;

    if v_file->'doc_type' is null or jsonb_typeof(v_file->'doc_type') <> 'string' or nullif(trim(v_file->>'doc_type'), '') is null then
      raise exception 'INVALID_STAGED_FILES';
    end if;

    v_storage_path := nullif(trim(v_file->>'storage_path'), '');
    v_original_name := nullif(trim(v_file->>'original_name'), '');
    v_content_type := lower(nullif(trim(v_file->>'content_type'), ''));
    v_payload_doc_type := lower(trim(v_file->>'doc_type'));

    if v_storage_path is null or v_original_name is null or v_content_type is null then
      raise exception 'INVALID_STAGED_FILES';
    end if;

    if v_file->>'size' is null or trim(v_file->>'size') !~ '^[0-9]+$' then
      raise exception 'INVALID_STAGED_FILES';
    end if;

    v_size := trim(v_file->>'size')::bigint;
    if v_size <= 0 or v_size > 52428800 then
      raise exception 'INVALID_STAGED_FILES';
    end if;

    if v_content_type not in (
      'application/pdf',
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      'application/vnd.ms-excel',
      'text/csv',
      'application/csv',
      'application/msword',
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      'image/jpeg',
      'image/jpg',
      'image/png'
    ) then
      raise exception 'INVALID_STAGED_FILES';
    end if;

    v_path_prefix := 'staged/' || auth.uid()::text || '/';
    if left(v_storage_path, length(v_path_prefix)) <> v_path_prefix then
      raise exception 'INVALID_STAGED_FILES';
    end if;

    v_path_suffix := substring(v_storage_path from length(v_path_prefix) + 1);
    if v_path_suffix is null or v_path_suffix = '' then
      raise exception 'INVALID_STAGED_FILES';
    end if;

    if position(E'\\' in v_storage_path) > 0 or v_storage_path ~ '[[:cntrl:]]' then
      raise exception 'INVALID_STAGED_FILES';
    end if;

    for v_path_segment in select * from unnest(regexp_split_to_array(v_path_suffix, '/')) loop
      if v_path_segment is null or v_path_segment = '' or v_path_segment in ('.', '..') then
        raise exception 'INVALID_STAGED_FILES';
      end if;
    end loop;

    if v_storage_path = any(v_seen_storage_paths) then
      raise exception 'INVALID_STAGED_FILES';
    end if;
    v_seen_storage_paths := array_append(v_seen_storage_paths, v_storage_path);

    if v_payload_doc_type in ('rent_roll', 't12', 't12_or_operating_statement') then
      if v_payload_doc_type = 'rent_roll' then
        v_has_rent_roll := true;
      else
        v_has_t12 := true;
      end if;
    elsif v_payload_doc_type in ('supporting', 'supporting_documents', 'supporting_documents_ui') then
      v_has_supporting_docs := true;
    else
      raise exception 'INVALID_STAGED_FILES';
    end if;

    if v_payload_doc_type = 't12_or_operating_statement' then
      v_payload_doc_type := 't12';
    elsif v_payload_doc_type in ('supporting_documents', 'supporting_documents_ui') then
      v_payload_doc_type := 'supporting';
    end if;

    v_normalized_files := v_normalized_files || jsonb_build_array(
      jsonb_build_object(
        'storage_path', v_storage_path,
        'original_name', v_original_name,
        'content_type', v_content_type,
        'size', v_size,
        'doc_type', v_payload_doc_type
      )
    );
  end loop;

  if not v_has_t12 or not v_has_rent_roll then
    raise exception 'MISSING_REQUIRED_CORE_DOCUMENTS'
      using detail = 'Upload both a Rent Roll and a T12 before starting analysis.';
  end if;

  if p_report_type = 'screening' and v_has_supporting_docs then
    raise exception 'SCREENING_SUPPORTING_DOCUMENTS_NOT_ALLOWED'
      using detail = 'Screening accepts only a Rent Roll and a T12.';
  end if;

  if p_report_type = 'underwriting' and not v_has_supporting_docs then
    raise exception 'MISSING_REQUIRED_SUPPORTING_DOCUMENT'
      using detail = 'Underwriting requires at least one supporting due diligence document.';
  end if;

  for v_file in select * from jsonb_array_elements(v_normalized_files) loop
    v_storage_path := nullif(trim(v_file->>'storage_path'), '');
    v_size := (v_file->>'size')::bigint;
    v_content_type := lower(nullif(trim(v_file->>'content_type'), ''));

    select *
      into strict v_storage_object_row
    from storage.objects
    where bucket_id = 'staged_uploads'
      and name = v_storage_path
    for update;

    v_object_size_text := nullif(trim(v_storage_object_row.metadata->>'size'), '');
    if v_object_size_text is not null then
      if v_object_size_text !~ '^[0-9]+$' then
        raise exception 'INVALID_STAGED_FILES';
      end if;

      if v_object_size_text::bigint <> v_size then
        raise exception 'INVALID_STAGED_FILES';
      end if;
    end if;

    if lower(coalesce(v_storage_object_row.metadata->>'mimetype', '')) <> v_content_type then
      raise exception 'INVALID_STAGED_FILES';
    end if;
  end loop;

  select id, product_type
    into v_purchase_id, v_product_type
  from public.report_purchases
  where user_id = auth.uid()
    and product_type = p_report_type
    and consumed_at is null
  order by created_at asc
  for update skip locked
  limit 1;

  if v_purchase_id is null then
    raise exception 'PURCHASE_NOT_AVAILABLE';
  end if;

  if v_product_type not in ('screening','underwriting') then
    raise exception 'INVALID_REPORT_TYPE';
  end if;

  insert into public.analysis_jobs (
    user_id,
    report_type,
    purchase_id,
    property_name,
    status,
    started_at
  )
  values (
    auth.uid(),
    v_product_type,
    v_purchase_id,
    nullif(p_job_payload->>'property_name',''),
    'queued',
    null
  )
  returning id into v_job_id;

  for v_file in select * from jsonb_array_elements(v_normalized_files) loop
    v_storage_path := nullif(trim(v_file->>'storage_path'), '');
    v_original_name := nullif(trim(v_file->>'original_name'), '');
    v_content_type := nullif(trim(v_file->>'content_type'), '');
    v_size := (v_file->>'size')::bigint;
    v_doc_type := lower(trim(coalesce(v_file->>'doc_type', '')));

    if v_doc_type = '' then
      raise exception 'INVALID_STAGED_FILES';
    end if;

    insert into public.analysis_job_files (
      job_id,
      user_id,
      bucket,
      object_path,
      original_filename,
      mime_type,
      bytes,
      doc_type,
      parse_status
    )
    values (
      v_job_id,
      auth.uid(),
      'staged_uploads',
      v_storage_path,
      v_original_name,
      v_content_type,
      v_size,
      v_doc_type,
      'pending'
    );
  end loop;

  update public.report_purchases
  set job_id = v_job_id,
      consumed_at = now()
  where id = v_purchase_id
    and consumed_at is null;

  if not found then
    raise exception 'PURCHASE_NOT_AVAILABLE';
  end if;

  return query select v_job_id, v_purchase_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.finalize_worker_publication(p_job_id uuid, p_worker_attempt_id uuid, p_expected_current_status text, p_claimed_by text)
 RETURNS SETOF analysis_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'storage', 'pg_temp'
AS $function$
declare
  v_now timestamptz := now();
  v_job public.analysis_jobs%rowtype;
  v_report public.reports%rowtype;
  v_manifest public.analysis_artifacts%rowtype;
  v_delivery public.analysis_artifacts%rowtype;
  v_decision jsonb;
  v_storage storage.objects%rowtype;
  v_action text;
  v_existing public.report_publication_receipts%rowtype;
begin
  select * into v_job from public.analysis_jobs where id = p_job_id for update;
  if not found then return; end if;
  if v_job.status <> p_expected_current_status
     or v_job.worker_attempt_id is distinct from p_worker_attempt_id
     or v_job.worker_claimed_by is distinct from nullif(btrim(coalesce(p_claimed_by,'')), '')
     or v_job.worker_lease_expires_at is null
     or v_job.worker_lease_expires_at <= v_now then return; end if;
  if v_job.admission_receipt_id is null
     or v_job.product_identity not in ('screening','full_underwriting')
     or v_job.report_family <> v_job.product_identity then
    raise exception 'PUBLICATION_GOVERNED_ADMISSION_REQUIRED';
  end if;
  if v_job.report_id is null then raise exception 'PUBLICATION_REPORT_LINK_REQUIRED'; end if;

  select * into v_report from public.reports where id = v_job.report_id for update;
  if not found then raise exception 'PUBLICATION_REPORT_NOT_FOUND'; end if;
  if v_report.user_id <> v_job.user_id then raise exception 'PUBLICATION_OWNER_LINEAGE_MISMATCH'; end if;
  if v_report.status <> 'published' then raise exception 'PUBLICATION_REPORT_ROW_NOT_READY'; end if;
  if v_report.revision_request_key is null then raise exception 'PUBLICATION_REVISION_REQUEST_KEY_REQUIRED'; end if;
  if v_report.revision_source_job_id is distinct from v_job.id then
    raise exception 'PUBLICATION_REVISION_SOURCE_JOB_MISMATCH';
  end if;
  if (v_job.product_identity = 'screening' and v_report.report_type <> 'screening')
     or (v_job.product_identity = 'full_underwriting' and v_report.report_type <> 'underwriting') then
    raise exception 'PUBLICATION_PRODUCT_REPORT_MISMATCH';
  end if;

  select * into v_storage
  from storage.objects o
  where o.bucket_id = 'generated_reports' and o.name = v_report.storage_path
  limit 1;
  if not found then raise exception 'PUBLICATION_GENERATED_OBJECT_MISSING'; end if;

  select * into v_manifest
  from public.analysis_artifacts a
  where a.job_id = v_job.id
    and a.user_id = v_job.user_id
    and a.type = 'report_quality_manifest'
  order by a.created_at desc limit 1;
  if not found then raise exception 'PUBLICATION_QUALITY_MANIFEST_REQUIRED'; end if;

  select * into v_delivery
  from public.analysis_artifacts a
  where a.job_id = v_job.id
    and a.user_id = v_job.user_id
    and a.type = 'delivery_gate_decision'
  order by a.created_at desc limit 1;
  if not found then raise exception 'PUBLICATION_CANONICAL_DELIVERY_DECISION_REQUIRED'; end if;

  v_decision := coalesce(v_delivery.payload->'deliveryDecisionState', v_delivery.payload);
  if coalesce(v_decision->>'source','') <> 'canonical_delivery_decision' then
    raise exception 'PUBLICATION_DELIVERY_DECISION_NOT_CANONICAL';
  end if;
  if coalesce((v_decision->>'customer_delivery_allowed')::boolean, false) is not true then
    raise exception 'PUBLICATION_DELIVERY_NOT_ALLOWED';
  end if;
  if coalesce((v_decision->>'core_valid_required_coverage')::boolean, false) is not true then
    raise exception 'PUBLICATION_CORE_COVERAGE_NOT_VALID';
  end if;

  v_action := case
    when lower(coalesce(v_decision->>'delivery_gate_status','')) like '%quality%'
      or lower(coalesce(v_manifest.payload->>'publication_state','')) like '%quality%'
      then 'DELIVER_WITH_QUALITY_INCIDENT'
    else 'DELIVER'
  end;

  select * into v_existing
  from public.report_publication_receipts r
  where r.job_id = v_job.id
  for update;

  if found then
    if v_existing.report_id <> v_report.id
       or v_existing.revision_request_key <> v_report.revision_request_key
       or v_existing.storage_path <> v_report.storage_path
       or v_existing.manifest_artifact_id <> v_manifest.id
       or v_existing.delivery_gate_artifact_id <> v_delivery.id then
      raise exception 'PUBLICATION_RECEIPT_IDEMPOTENCY_CONFLICT';
    end if;
  else
    insert into public.report_publication_receipts(
      job_id, report_id, user_id, product_identity, report_family,
      revision_request_key, storage_path, storage_object_id, storage_metadata,
      manifest_artifact_id, delivery_gate_artifact_id, canonical_delivery_action,
      publication_status, completed_at
    ) values (
      v_job.id, v_report.id, v_job.user_id, v_job.product_identity, v_job.report_family,
      v_report.revision_request_key, v_report.storage_path, v_storage.id, coalesce(v_storage.metadata,'{}'::jsonb),
      v_manifest.id, v_delivery.id, v_action, 'complete', v_now
    );
  end if;

  return query
  update public.analysis_jobs j
     set status = 'published',
         worker_lease_expires_at = null,
         worker_last_heartbeat_at = v_now,
         terminal_domain = null,
         last_checkpoint = 'published',
         last_checkpoint_at = v_now
   where j.id = v_job.id
     and j.status = p_expected_current_status
     and j.worker_attempt_id = p_worker_attempt_id
     and j.worker_claimed_by = nullif(btrim(coalesce(p_claimed_by,'')), '')
  returning j.*;
end;
$function$

CREATE OR REPLACE FUNCTION public.requeue_worker_job(p_job_id uuid, p_claimed_by text DEFAULT NULL::text, p_allow_expired_lease_recovery boolean DEFAULT false)
 RETURNS SETOF analysis_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_now timestamptz := now();
  v_claimed_by text := nullif(btrim(coalesce(p_claimed_by, '')), '');
  v_job public.analysis_jobs%rowtype;
  v_limit integer;
  v_episode public.worker_recovery_episodes%rowtype;
begin
  select * into v_job from public.analysis_jobs where id = p_job_id for update;
  if not found or v_job.status = 'published' then return; end if;
  if v_job.admission_receipt_id is null then return; end if;

  v_limit := public.worker_effective_attempt_limit(p_job_id);
  if coalesce(v_job.worker_attempt_count, 0) >= v_limit then return; end if;

  if v_job.status in ('extracting','underwriting','scoring','rendering','pdf_generating','publishing') then
    if v_job.worker_claimed_by = v_claimed_by
       and v_job.worker_lease_expires_at is not null
       and (
         v_job.worker_lease_expires_at > v_now
         or (p_allow_expired_lease_recovery and v_job.worker_lease_expires_at <= v_now)
       ) then
      return query
      update public.analysis_jobs j
         set status = 'queued', started_at = null,
             worker_attempt_id = null, worker_lease_expires_at = null,
             worker_claimed_at = null, worker_last_heartbeat_at = null,
             worker_claimed_by = null, dead_lettered_at = null,
             error_code = null, error_message = null, failure_reason = null,
             last_checkpoint = coalesce(j.last_checkpoint, v_job.status),
             last_checkpoint_at = v_now
       where j.id = p_job_id
      returning j.*;
    end if;
    return;
  end if;

  if v_job.status in ('failed','dead_letter') then
    select * into v_episode
    from public.worker_recovery_episodes e
    where e.job_id = p_job_id and e.status = 'open'
    for update;
    if not found or v_episode.attempts_consumed >= v_episode.retry_budget then return; end if;

    return query
    update public.analysis_jobs j
       set status = 'queued', started_at = null,
           worker_attempt_id = null, worker_lease_expires_at = null,
           worker_claimed_at = null, worker_last_heartbeat_at = null,
           worker_claimed_by = null, dead_lettered_at = null,
           error_code = null, error_message = null, failure_reason = null,
           terminal_domain = null,
           recovery_episode_id = v_episode.id,
           last_checkpoint = coalesce(v_episode.resume_checkpoint, j.last_checkpoint, 'admitted'),
           last_checkpoint_at = v_now
     where j.id = p_job_id
    returning j.*;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.transition_worker_job(p_job_id uuid, p_worker_attempt_id uuid, p_expected_current_status text, p_next_status text, p_claimed_by text DEFAULT NULL::text)
 RETURNS SETOF analysis_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_now timestamptz := now();
  v_claimed_by text := nullif(btrim(coalesce(p_claimed_by, '')), '');
begin
  if p_next_status = 'published' then
    return query select * from public.finalize_worker_publication(
      p_job_id, p_worker_attempt_id, p_expected_current_status, v_claimed_by
    );
    return;
  end if;

  if p_next_status = 'queued' then
    perform 1 from public.analysis_jobs j
    where j.id = p_job_id
      and j.worker_attempt_id = p_worker_attempt_id
      and j.worker_claimed_by = v_claimed_by
      and j.status = p_expected_current_status;
    if not found then return; end if;
    return query select * from public.requeue_worker_job(p_job_id, v_claimed_by, false);
    return;
  end if;

  return query
  update public.analysis_jobs j
     set status = p_next_status,
         worker_last_heartbeat_at = v_now,
         worker_lease_expires_at = v_now + public.worker_lease_duration(),
         last_checkpoint = case
           when p_next_status in ('underwriting','scoring','rendering','pdf_generating','publishing') then p_next_status
           else j.last_checkpoint
         end,
         last_checkpoint_at = case
           when p_next_status in ('underwriting','scoring','rendering','pdf_generating','publishing') then v_now
           else j.last_checkpoint_at
         end
   where j.id = p_job_id
     and j.worker_attempt_id = p_worker_attempt_id
     and j.worker_claimed_by = v_claimed_by
     and j.status = p_expected_current_status
     and j.dead_lettered_at is null
     and j.worker_lease_expires_at is not null
     and j.worker_lease_expires_at > v_now
  returning j.*;
end;
$function$
